/**
 * Deterministic, offline directory renderer.
 * Source of truth: servers/<category>/<slug>/server.json + config/mcp-taxonomy.json.
 * Generated files: README.md and categories/<category>.md, no server metadata movement.
 * Run: node scripts/generate-readme.mjs [--check]
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const GENERATED_MARKER = '<!-- Generated by scripts/generate-readme.mjs. Edit server.json and the taxonomy, not these pages. -->';
const rootDefault = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const displayNames = {
  'browser-automation': 'Browser Automation',
  'code-hosting': 'Code Hosting',
  'communication': 'Communication',
  'data': 'Data & APIs',
  'design': 'Design & Media',
  'developer-tools': 'Developer Tools',
  'files': 'Files',
  'knowledge': 'Knowledge',
  'observability': 'Observability',
  'orchestration': 'Orchestration',
  'security': 'Security'
};

function markdown(value) {
  return String(value ?? '')
    .replace(/[\r\n]+/g, ' ')
    .replace(/\\/g, '\\\\')
    .replace(/\|/g, '\\|')
    .replace(/[<>]/g, c => c === '<' ? '&lt;' : '&gt;')
    .replace(/([*_`\[\]])/g, '\\$1');
}

function safeLink(url, label) {
  if (typeof url !== 'string' || !url.trim()) return null;
  let parsed;
  try { parsed = new URL(url); } catch { throw new Error(`Invalid ${label} URL`); }
  if (parsed.protocol !== 'https:' || parsed.username || parsed.password) throw new Error(`Invalid ${label} HTTPS URL`);
  // Brackets and parentheses can break Markdown link destinations.
  return parsed.href.replace(/[()<>]/g, c => encodeURIComponent(c));
}

function listEntries(root, knownCategories) {
  const all = [];
  const servers = path.join(root, 'servers');
  if (!fs.existsSync(servers)) return all;
  for (const categoryDir of fs.readdirSync(servers, { withFileTypes: true }).filter(x => x.isDirectory())) {
    const category = categoryDir.name;
    const categoryPath = path.join(servers, category);
    for (const slugDir of fs.readdirSync(categoryPath, { withFileTypes: true }).filter(x => x.isDirectory())) {
      const filename = path.join(categoryPath, slugDir.name, 'server.json');
      if (!fs.existsSync(filename)) continue;
      if (!knownCategories.includes(category)) throw new Error(`Unknown category in ${filename}`);
      const entry = JSON.parse(fs.readFileSync(filename, 'utf8'));
      if (entry.slug !== slugDir.name || entry.category !== category) throw new Error(`Entry path and category mismatch: ${filename}`);
      for (const field of ['name', 'description', 'homepage_url']) {
        if (typeof entry[field] !== 'string' || !entry[field].trim()) throw new Error(`Missing ${field}: ${filename}`);
      }
      all.push(entry);
    }
  }
  return all;
}

export function renderCatalog(root = rootDefault) {
  const taxonomy = JSON.parse(fs.readFileSync(path.join(root, 'config/mcp-taxonomy.json'), 'utf8'));
  const primary = taxonomy.primary_categories;
  if (!primary || typeof primary !== 'object' || Array.isArray(primary)) throw new Error('Invalid primary category taxonomy');
  const categories = Object.keys(primary).sort((a, b) =>
    (displayNames[a] || a).localeCompare(displayNames[b] || b, 'en'));
  const entries = listEntries(root, categories);
  const byCategory = new Map(categories.map(category => [category, []]));
  for (const entry of entries) byCategory.get(entry.category).push(entry);
  for (const group of byCategory.values()) group.sort((a, b) => a.name.localeCompare(b.name, 'en') || a.slug.localeCompare(b.slug, 'en'));

  const index = [
    GENERATED_MARKER,
    '# Awesome MCP',
    '',
    'A curated directory of Model Context Protocol (MCP) servers maintained by WunderCorp. Browse a category to see its servers and project links.',
    '',
    '## Browse MCP servers by category',
    '',
    '| Category | Servers | Scope |',
    '| --- | ---: | --- |'
  ];
  for (const category of categories) {
    index.push(`| [${markdown(displayNames[category] || category)}](categories/${category}.md) | ${byCategory.get(category).length} | ${markdown(primary[category])} |`);
  }
  index.push('', `**${entries.length} servers** across ${categories.length} categories.`, '',
    '## Submit an MCP server', '',
    'Add or update one `servers/<category>/<slug>/server.json` per pull request. The category pages are generated from this metadata; do not edit generated Markdown in new submissions.', '',
    'See [Contributing](CONTRIBUTING.md) and the [MCP server template](templates/server.json).', '',
    '```bash', 'node scripts/validate-catalog.mjs', 'node scripts/validate-taxonomy.mjs', 'node scripts/generate-readme.mjs', '```', '',
    '## Review and safety', '',
    'Directory inclusion is not a security certification. Safety review is a separate, point-in-time process; unscanned listings have not been verified safe.', '',
    '## License', '',
    'Directory metadata is MIT licensed unless an entry says otherwise. Listed projects retain their own licenses.', '');

  const outputs = new Map([['README.md', index.join('\n').replace(/\n+$/, '') + '\n']]);
  for (const category of categories) {
    const name = displayNames[category] || category;
    const group = byCategory.get(category);
    const lines = [GENERATED_MARKER, `# ${markdown(name)} MCP servers`, '',
      '[← All categories](../README.md)', '', markdown(primary[category]), '',
      `**${group.length} ${group.length === 1 ? 'server' : 'servers'}**`, ''];
    if (!group.length) lines.push('No MCP servers in this category yet.', '');
    else {
      lines.push('| Server | Description | Transport | Project links |', '| --- | --- | --- | --- |');
      for (const entry of group) {
        const links = [];
        for (const [field, label] of [['homepage_url', 'Homepage'], ['repository_url', 'GitHub'], ['package_url', 'Package']]) {
          const url = safeLink(entry[field], field);
          if (url) links.push(`[${label}](${url})`);
        }
        const transports = Array.isArray(entry.transports) ? entry.transports.join(', ') : 'Not specified';
        lines.push(`| ${markdown(entry.name)} | ${markdown(entry.description)} | ${markdown(transports)} | ${links.join(' · ')} |`);
      }
      lines.push('');
    }
    lines.push('**Listing is not a safety certification.** Check the project’s documentation and permissions before connecting it.', '');
    outputs.set(`categories/${category}.md`, lines.join('\n').replace(/\n+$/, '') + '\n');
  }
  return { outputs, entryCount: entries.length, categories: categories.length };
}

export function synchronize(root = rootDefault, check = false) {
  const { outputs, entryCount, categories } = renderCatalog(root);
  const categoryDir = path.join(root, 'categories');
  const mismatches = [];
  for (const [relative, content] of outputs) {
    const full = path.join(root, relative);
    if (!fs.existsSync(full) || fs.readFileSync(full, 'utf8') !== content) {
      mismatches.push(relative);
      if (!check) {
        fs.mkdirSync(path.dirname(full), { recursive: true });
        fs.writeFileSync(full, content, 'utf8');
      }
    }
  }
  if (fs.existsSync(categoryDir)) {
    for (const file of fs.readdirSync(categoryDir)) {
      if (!file.endsWith('.md') || outputs.has(`categories/${file}`)) continue;
      const full = path.join(categoryDir, file);
      if (fs.statSync(full).isFile() && fs.readFileSync(full, 'utf8').startsWith(GENERATED_MARKER)) {
        mismatches.push(`categories/${file}`);
        if (!check) fs.unlinkSync(full);
      }
    }
  }
  if (check && mismatches.length) throw new Error(`Generated catalog is stale: ${mismatches.join(', ')}`);
  return { changed: mismatches, entryCount, categories };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length > 3 || (process.argv[2] && process.argv[2] !== '--check')) {
    console.error('Usage: node scripts/generate-readme.mjs [--check]');
    process.exitCode = 2;
  } else {
    try {
      const output = synchronize(rootDefault, process.argv[2] === '--check');
      console.log(`${process.argv[2] === '--check' ? 'Checked' : 'Generated'} ${output.entryCount} MCP entries across ${output.categories} category pages${output.changed.length ? `; changed: ${output.changed.join(', ')}` : ''}.`);
    } catch (error) { console.error(error.message); process.exitCode = 1; }
  }
}
